<template>
  <view class="home">
    <scroll-view class="home__content" scroll-y :show-scrollbar="false">
      <view class="home__scroll-inner">
        <!-- 顶部导航 + 品牌 Banner 一体红区 -->
        <view class="home__hero">
          <view class="home__nav" :style="navStyle">
            <view class="home__search" :style="searchStyle" @tap="goSearch">
              <view class="home__search-icon"></view>
              <text class="home__search-text">点击搜索</text>
            </view>
          </view>
          <text class="home__slogan">食材当日现备・好滋味有温度・新鲜现做</text>

          <view class="home__brand-banner">
            <text class="home__brand-name">{{ storeName }}</text>
            <view class="home__brand-tags">
              <text
                class="home__brand-tag"
                v-for="(tag, index) in brandTags"
                :key="index"
              >{{ tag }}</text>
            </view>
          </view>

          <view class="home__banner-section">
            <view class="home__banner-wrap">
              <swiper
                class="home__swiper"
                :circular="displayBanners.length > 1"
                :autoplay="displayBanners.length > 0"
                :interval="4000"
                :duration="600"
                indicator-dots
                indicator-color="rgba(255,255,255,0.45)"
                indicator-active-color="#FFFFFF"
              >
                <swiper-item
                  v-for="(item, index) in displayBanners"
                  :key="index"
                  class="home__swiper-item"
                >
                  <image
                    v-if="item.image"
                    :src="item.image"
                    class="home__banner-image"
                    mode="aspectFill"
                  />
                  <view v-else class="home__banner-placeholder"></view>
                </swiper-item>
              </swiper>
            </view>
          </view>
        </view>

        <view class="home__sections">
          <!-- 服务入口：自提 / 外卖 -->
          <view class="home__primary-card">
            <view class="home__primary-item" @click="selectMode(1)">
              <view class="home__icon home__icon--store"></view>
              <text class="home__primary-name">自提</text>
              <text class="home__primary-desc">下单免排队</text>
            </view>
            <view class="home__primary-divider"></view>
            <view
              class="home__primary-item"
              :class="{ 'home__primary-item--disabled': shop && shop.deliveryEnable !== 1 }"
              @click="selectMode(3)"
            >
              <view class="home__icon home__icon--delivery"></view>
              <text class="home__primary-name">外卖</text>
              <text class="home__primary-desc">美味配送到家</text>
            </view>
          </view>

          <!-- 功能模块：积分 / 储值 / 优惠券 -->
          <view class="home__shortcut-row">
            <view
              class="home__shortcut-item"
              v-for="item in shortcuts"
              :key="item.name"
              @tap="onShortcutTap(item)"
            >
              <view class="home__icon" :class="item.iconClass"></view>
              <text class="home__shortcut-name">{{ item.name }}</text>
              <text class="home__shortcut-desc">{{ item.desc }}</text>
            </view>
          </view>

          <!-- 招牌推荐 -->
          <view class="home__recommend">
            <view class="home__recommend-header">
              <text class="home__recommend-title">招牌推荐</text>
              <text class="home__recommend-link" @tap="goMenu">去点单 ></text>
            </view>

            <view class="home__dish-list" v-if="recommendDishes.length">
              <view
                class="home__dish-item"
                v-for="(dish, index) in recommendDishes"
                :key="dish.id"
                :class="{ 'home__dish-item--last': index === recommendDishes.length - 1 }"
                @tap="selectSpec(dish)"
              >
                <view class="home__dish-image-wrap">
                  <image class="home__dish-image" :src="dish.image" mode="aspectFill" />
                  <view class="home__dish-badge" v-if="dish.badge">
                    <text class="home__dish-badge-text">{{ dish.badge }}</text>
                  </view>
                </view>
                <view class="home__dish-info">
                  <text class="home__dish-name">{{ dish.title }}</text>
                  <text class="home__dish-desc">{{ dish.intro || '匠心制作，每日新鲜' }}</text>
                  <view class="home__dish-bottom">
                    <text class="home__dish-price">¥{{ dish.price }}</text>
                    <view class="home__dish-btn" @tap.stop="selectSpec(dish)">
                      <text class="home__dish-btn-text">选规格</text>
                    </view>
                  </view>
                </view>
              </view>
            </view>

            <view class="home__recommend-empty" v-if="!recommendLoading && recommendDishes.length === 0">
              <text class="home__recommend-empty-text">暂无推荐菜品</text>
            </view>
          </view>
        </view>

        <view class="home__bottom-space"></view>
      </view>
    </scroll-view>

    <view class="app-tab-bar">
      <view
        v-for="(item, index) in tabbarList"
        :key="index"
        class="app-tab-item"
        @tap.stop="switchTabbar(item, index)"
      >
        <image
          v-if="item.selected || item.unselected"
          class="app-tab-icon"
          :src="tabbarSelected === index ? item.selected : item.unselected"
          mode="aspectFit"
        />
        <text
          class="app-tab-text"
          :style="{ color: tabbarSelected === index ? tabbarSelectedColor : tabbarDefaultColor }"
        >
          {{ item.name }}
        </text>
      </view>
    </view>
  </view>
</template>

<script>
import { orderApi, decorateApi } from '../../api/index'
import { DEFAULT_SHOP_ID } from '../../utils/config'
import { resolveImageUrl } from '../../utils/image'
import tabbarPageMixin from '../../mixins/tabbar-page'
import { getNavMetrics } from '../../utils/navbar'

export default {
  mixins: [tabbarPageMixin],
  data() {
    return {
      navMetrics: getNavMetrics(),
      menuButtonRight: 96,
      shop: null,
      aid: DEFAULT_SHOP_ID,
      banners: [],
      recommendDishes: [],
      recommendLoading: false,
      brandTags: ['好一个胃', '撑起一个家', '温暖一座城'],
      shortcuts: [
        { name: '积分商城', desc: '神秘好物等你来', iconClass: 'home__icon--points' },
        { name: '储值优惠', desc: '查看&绑定', iconClass: 'home__icon--wallet' },
        { name: '优惠券包', desc: '享多重优惠', iconClass: 'home__icon--coupon' }
      ]
    }
  },
  computed: {
    navStyle() {
      const { statusBarHeight, navBarHeight } = this.navMetrics
      return {
        paddingTop: `${statusBarHeight}px`,
        height: `${statusBarHeight + navBarHeight}px`,
        boxSizing: 'border-box'
      }
    },
    searchStyle() {
      return {
        marginRight: `${this.menuButtonRight}px`
      }
    },
    storeName() {
      return this.shop?.name || '粮兴坊'
    },
    displayBanners() {
      if (this.banners.length) return this.banners
      if (this.shop?.image) return [{ image: this.shop.image }]
      return [{ image: '' }]
    }
  },
  onLoad() {
    this.updateNavPadding()
  },
  onReady() {
    this.updateNavPadding()
  },
  onShow() {
    this.updateNavPadding()
    this.setupTabbar(0)
    this.loadPageContent()
  },
  methods: {
    updateNavPadding() {
      this.navMetrics = getNavMetrics()
      try {
        const sys = uni.getSystemInfoSync()
        if (typeof uni.getMenuButtonBoundingClientRect === 'function') {
          const menuButton = uni.getMenuButtonBoundingClientRect()
          if (menuButton && menuButton.left > 0) {
            this.menuButtonRight = sys.windowWidth - menuButton.left + 8
          }
        }
      } catch (e) {
        // keep fallback
      }
    },
    async loadShop() {
      try {
        const shop = await orderApi.shop(this.aid)
        if (shop?.image) {
          shop.image = resolveImageUrl(shop.image)
        }
        this.shop = shop
      } catch (e) {
        uni.showToast({ title: e.message || e, icon: 'none' })
      }
    },
    async loadDecoration() {
      try {
        const page = await decorateApi.page(1)
        const widgets = JSON.parse(page?.pageData || '[]')
        const bannerWidget = widgets.find((item) => item.name === 'banner')
        if (bannerWidget?.content?.enabled === 1 && Array.isArray(bannerWidget.content.data)) {
          this.banners = bannerWidget.content.data
            .filter((item) => item.image)
            .map((item) => ({
              ...item,
              image: resolveImageUrl(item.image)
            }))
        } else {
          this.banners = []
        }
      } catch (e) {
        this.banners = []
      }
    },
    async loadRecommend() {
      this.recommendLoading = true
      try {
        const list = await orderApi.menu(this.aid)
        const foods = []
        ;(Array.isArray(list) ? list : []).forEach((cate) => {
          ;(cate.foods || []).forEach((food) => {
            foods.push({
              ...food,
              image: resolveImageUrl(food.image)
            })
          })
        })
        this.recommendDishes = foods.slice(0, 5).map((food, index) => ({
          ...food,
          badge: index === 0 ? '招牌' : index === 1 ? '热卖' : ''
        }))
      } catch (e) {
        this.recommendDishes = []
      } finally {
        this.recommendLoading = false
      }
    },
    selectMode(mode) {
      if (mode === 3 && this.shop && this.shop.deliveryEnable !== 1) {
        uni.showToast({ title: '暂未开启外卖', icon: 'none' })
        return
      }
      uni.setStorageSync('diningMode', mode)
      if (mode === 3) {
        uni.navigateTo({ url: '/pages/address/list?select=1' })
        return
      }
      uni.navigateTo({ url: '/pages/menu/index' })
    },
    goMenu() {
      uni.setStorageSync('diningMode', 1)
      uni.navigateTo({ url: '/pages/menu/index' })
    },
    selectSpec() {
      this.goMenu()
    },
    goSearch() {
      uni.showToast({ title: '搜索功能开发中', icon: 'none' })
    },
    onShortcutTap() {
      uni.showToast({ title: '功能开发中', icon: 'none' })
    }
  }
}
</script>

<style lang="scss" scoped>
$page-pad: $spacing-page;
$section-gap: 20rpx;
$hero-red: #D92121;
$hero-orange: #FF8C42;

.home {
  display: flex;
  flex-direction: column;
  height: 100vh;
  background: $bg-page;

  &__scroll-inner {
    box-sizing: border-box;
  }

  &__content {
    flex: 1;
    background: $bg-page;
    overflow: hidden;
  }

  /* ===== 顶部红区：导航 + Banner ===== */
  &__hero {
    background: $hero-red;
    padding-bottom: 8rpx;
  }

  &__nav {
    display: flex;
    align-items: center;
    padding: 0 $page-pad;
  }

  &__search {
    flex: 1;
    display: flex;
    align-items: center;
    height: 64rpx;
    padding: 0 24rpx;
    background: rgba(255, 255, 255, 0.92);
    border-radius: 999rpx;
    box-sizing: border-box;
  }

  &__search-icon {
    width: 28rpx;
    height: 28rpx;
    border: 3rpx solid #CCCCCC;
    border-radius: 50%;
    position: relative;
    flex-shrink: 0;
    margin-right: 12rpx;

    &::after {
      content: '';
      position: absolute;
      width: 10rpx;
      height: 3rpx;
      background: #CCCCCC;
      border-radius: 2rpx;
      bottom: -2rpx;
      right: -6rpx;
      transform: rotate(45deg);
    }
  }

  &__search-text {
    font-size: 26rpx;
    color: #AAAAAA;
  }

  &__slogan {
    display: block;
    padding: 12rpx $page-pad 20rpx;
    font-size: 20rpx;
    color: rgba(255, 255, 255, 0.78);
    letter-spacing: 1rpx;
    line-height: 1.4;
  }

  &__brand-banner {
    margin: 0 $page-pad $section-gap;
    padding: 36rpx 32rpx 32rpx;
    border-radius: 32rpx;
    background: linear-gradient(135deg, $hero-red 0%, #E84520 45%, $hero-orange 100%);
    box-shadow: 0 8rpx 24rpx rgba(217, 33, 33, 0.22);
  }

  &__brand-name {
    display: block;
    font-size: 88rpx;
    font-weight: 900;
    color: #FFFFFF;
    letter-spacing: 10rpx;
    line-height: 1.15;
    text-shadow:
      2rpx 2rpx 0 rgba(0, 0, 0, 0.08),
      -2rpx 0 0 rgba(255, 255, 255, 0.15),
      2rpx 0 0 rgba(255, 255, 255, 0.15),
      0 2rpx 0 rgba(255, 255, 255, 0.15);
  }

  &__brand-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 12rpx;
    margin-top: 24rpx;
  }

  &__brand-tag {
    padding: 8rpx 20rpx;
    font-size: 22rpx;
    color: #6B3A1E;
    background: rgba(255, 220, 180, 0.85);
    border-radius: 999rpx;
    line-height: 1.3;
  }

  &__banner-section {
    padding: 0 $page-pad $section-gap;
  }

  &__banner-wrap {
    padding: 6rpx;
    border-radius: 28rpx;
    background: linear-gradient(135deg, $hero-red 0%, #E84520 50%, $hero-orange 100%);
    box-shadow: 0 8rpx 20rpx rgba(217, 33, 33, 0.18);
  }

  &__swiper {
    height: 320rpx;
    border-radius: 24rpx;
    overflow: hidden;
    background: linear-gradient(135deg, #C41E1E 0%, $hero-red 50%, #E84520 100%);
  }

  &__banner-image {
    width: 100%;
    height: 320rpx;
  }

  /* ===== 内容区 ===== */
  &__sections {
    padding: $section-gap $page-pad 0;
    display: flex;
    flex-direction: column;
    gap: $section-gap;
  }

  &__primary-card {
    display: flex;
    align-items: stretch;
    background: #FFFFFF;
    border-radius: 28rpx;
    box-shadow: $shadow-card;
    overflow: hidden;
  }

  &__primary-item {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 36rpx 16rpx 32rpx;

    &:active {
      background: #FAFAFA;
    }

    &--disabled {
      opacity: 0.45;
    }
  }

  &__primary-divider {
    width: 1rpx;
    align-self: stretch;
    background: #F0EBE6;
    margin: 28rpx 0;
  }

  &__primary-name {
    margin-top: 16rpx;
    font-size: 32rpx;
    font-weight: bold;
    color: #1A1A1A;
  }

  &__primary-desc {
    margin-top: 8rpx;
    font-size: 22rpx;
    color: #999999;
  }

  &__shortcut-row {
    display: flex;
    gap: 16rpx;
  }

  &__shortcut-item {
    flex: 1;
    background: #FFFFFF;
    border-radius: 22rpx;
    padding: 28rpx 10rpx 24rpx;
    display: flex;
    flex-direction: column;
    align-items: center;
    box-shadow: $shadow-card;
    min-height: 172rpx;
    box-sizing: border-box;

    &:active {
      opacity: 0.88;
    }
  }

  &__shortcut-name {
    margin-top: 14rpx;
    font-size: 26rpx;
    font-weight: bold;
    color: #1A1A1A;
  }

  &__shortcut-desc {
    margin-top: 6rpx;
    font-size: 20rpx;
    color: #999999;
    text-align: center;
    line-height: 1.35;
    padding: 0 4rpx;
  }

  /* ===== 红色线描图标 ===== */
  &__icon {
    width: 52rpx;
    height: 52rpx;
    position: relative;
    box-sizing: border-box;

    &--store {
      border: 3rpx solid $hero-red;
      border-radius: 8rpx;

      &::before {
        content: '';
        position: absolute;
        top: -14rpx;
        left: 50%;
        transform: translateX(-50%);
        width: 0;
        height: 0;
        border-left: 16rpx solid transparent;
        border-right: 16rpx solid transparent;
        border-bottom: 14rpx solid $hero-red;
      }

      &::after {
        content: '';
        position: absolute;
        bottom: 10rpx;
        left: 50%;
        transform: translateX(-50%);
        width: 20rpx;
        height: 20rpx;
        border: 3rpx solid $hero-red;
        border-radius: 2rpx;
      }
    }

    &--delivery {
      border: 3rpx solid $hero-red;
      border-radius: 8rpx 8rpx 4rpx 4rpx;
      margin-top: 4rpx;

      &::before {
        content: '';
        position: absolute;
        top: 14rpx;
        left: -10rpx;
        width: 14rpx;
        height: 14rpx;
        border: 3rpx solid $hero-red;
        border-radius: 50%;
        background: transparent;
      }

      &::after {
        content: '';
        position: absolute;
        top: 14rpx;
        right: -10rpx;
        width: 14rpx;
        height: 14rpx;
        border: 3rpx solid $hero-red;
        border-radius: 50%;
        background: transparent;
      }
    }

    &--points {
      border: 3rpx solid $hero-red;
      border-radius: 50%;

      &::before {
        content: '';
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -60%);
        width: 6rpx;
        height: 6rpx;
        background: $hero-red;
        border-radius: 50%;
        box-shadow:
          -10rpx 6rpx 0 $hero-red,
          10rpx 6rpx 0 $hero-red,
          0 14rpx 0 $hero-red;
      }
    }

    &--wallet {
      border: 3rpx solid $hero-red;
      border-radius: 8rpx;

      &::before {
        content: '';
        position: absolute;
        top: -8rpx;
        left: 50%;
        transform: translateX(-50%);
        width: 20rpx;
        height: 12rpx;
        border: 3rpx solid $hero-red;
        border-bottom: none;
        border-radius: 8rpx 8rpx 0 0;
      }

      &::after {
        content: '';
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 12rpx;
        height: 12rpx;
        border: 3rpx solid $hero-red;
        border-radius: 50%;
      }
    }

    &--coupon {
      border: 3rpx dashed $hero-red;
      border-radius: 6rpx;

      &::before,
      &::after {
        content: '';
        position: absolute;
        top: 50%;
        transform: translateY(-50%);
        width: 10rpx;
        height: 10rpx;
        background: #FFFFFF;
        border: 3rpx solid $hero-red;
        border-radius: 50%;
      }

      &::before {
        left: -8rpx;
      }

      &::after {
        right: -8rpx;
      }
    }
  }

  /* ===== 招牌推荐 ===== */
  &__recommend {
    padding-top: 8rpx;
  }

  &__recommend-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16rpx;
  }

  &__recommend-title {
    font-size: 34rpx;
    font-weight: bold;
    color: #1A1A1A;
  }

  &__recommend-link {
    font-size: 26rpx;
    color: $hero-red;
    font-weight: 500;
    padding: 8rpx 0;
  }

  &__dish-list {
    background: #FFFFFF;
    border-radius: 24rpx;
    box-shadow: $shadow-card;
    padding: 0 24rpx;
  }

  &__dish-item {
    display: flex;
    align-items: stretch;
    padding: 24rpx 0;
    border-bottom: 1rpx solid #F0EBE6;

    &--last {
      border-bottom: none;
    }

    &:active {
      opacity: 0.92;
    }
  }

  &__dish-image-wrap {
    position: relative;
    flex-shrink: 0;
  }

  &__dish-image {
    width: 168rpx;
    height: 168rpx;
    border-radius: 16rpx;
    background: #F5F0EB;
  }

  &__dish-badge {
    position: absolute;
    top: 0;
    left: 0;
    background: $hero-red;
    border-radius: 16rpx 0 12rpx 0;
    padding: 4rpx 14rpx;
  }

  &__dish-badge-text {
    font-size: 20rpx;
    color: #FFFFFF;
    font-weight: 500;
  }

  &__dish-info {
    flex: 1;
    margin-left: 20rpx;
    min-width: 0;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: 4rpx 0;
  }

  &__dish-name {
    font-size: 30rpx;
    font-weight: bold;
    color: #1A1A1A;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  &__dish-desc {
    margin-top: 8rpx;
    font-size: 22rpx;
    color: #999999;
    overflow: hidden;
    text-overflow: ellipsis;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    -webkit-box-orient: vertical;
    line-height: 1.4;
  }

  &__dish-bottom {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 12rpx;
  }

  &__dish-price {
    font-size: 34rpx;
    font-weight: bold;
    color: #1A1A1A;
  }

  &__dish-btn {
    flex-shrink: 0;
    background: $hero-red;
    border-radius: 999rpx;
    padding: 12rpx 28rpx;
  }

  &__dish-btn-text {
    font-size: 24rpx;
    color: #FFFFFF;
    font-weight: 500;
    white-space: nowrap;
  }

  &__recommend-empty {
    padding: 60rpx 0 40rpx;
    text-align: center;
    background: #FFFFFF;
    border-radius: 24rpx;
    box-shadow: $shadow-card;
  }

  &__recommend-empty-text {
    font-size: 26rpx;
    color: #999999;
  }

  &__bottom-space {
    height: calc(120rpx + env(safe-area-inset-bottom));
  }
}
</style>
